import {demoContent,blankState,dateKey,weekDays,suggestedDays} from './data.js';
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={home:'M3 10 12 3l9 7v11h-6v-7H9v7H3z',training:'M7 8v8M4 9v6m13-7v8m3-7v6M7 12h10',food:'M12 3a9 9 0 1 0 9 9h-9V3Zm3 0v6h6a8 8 0 0 0-6-6',progress:'m4 17 5-5 4 3 7-10M4 4v16h17',community:'M21 11a8 8 0 0 1-8 8H6l-4 3 1-7a8 8 0 1 1 18-4Z',profile:'M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0ZM4 21v-3a8 8 0 0 1 16 0v3',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4',search:'M21 21l-5-5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0Z',arrow:'M4 12h16m-6-6 6 6-6 6',check:'m5 12 4 4L20 5',play:'m9 5 11 7-11 7Z',water:'M12 2S4 11 4 15a8 8 0 0 0 16 0c0-4-8-13-8-13Z',calendar:'M4 5h16v16H4ZM8 2v6m8-6v6M4 10h16',book:'M12 5C8 2 4 3 2 4v16c3-2 6-2 10 0 4-2 7-2 10 0V4c-3-1-6-2-10 1Zm0 0v15',heart:'M20 5c-3-3-7-1-8 2-1-3-5-5-8-2-5 5 8 15 8 15S25 10 20 5Z',clock:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0ZM12 7v5l3 2',close:'m6 6 12 12M6 18 18 6',plus:'M12 4v16M4 12h16',logout:'M9 3H3v18h6m5-15 6 6-6 6M8 12h12',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8ZM12 2v3m0 14v3M2 12h3m14 0h3M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2',leaf:'M20 3C7 1 1 7 5 15s18 6 15-12ZM5 20 16 8'};
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.book}"/></svg>`;
const brand=()=>`<a class="brand" href="#home"><img src="/assets/mark.svg" alt=""><div><strong>Lara Castelli</strong><small>SEU CORPO. SEU CUIDADO.</small></div></a>`;
const navs=[['home','Início'],['training','Meus treinos'],['food','Alimentação'],['progress','Minha evolução'],['care','Acompanhamento'],['community','Comunidade'],['feed','Novidades'],['profile','Meu perfil']];
let demo=sessionStorage.getItem('lara-demo')==='1',user=null,state=blankState(),content=[],posts=[],tickets=[],page='home',tab='library',week=0,month=1,search='',saveQueue=Promise.resolve(),timerId=null,timerEnd=0,timerRemaining=60,toastId;
const isDemo=()=>demo;
async function api(url,method='GET',body){const r=await fetch('/api'+url,{method,credentials:'same-origin',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined});if(!r.ok){let error;try{error=(await r.json()).error}catch{}throw Error(error||'Não foi possível concluir a solicitação.');}return r.json();}
function toast(message){clearTimeout(toastId);$('#toast').textContent=message;$('#toast').classList.add('visible');toastId=setTimeout(()=>$('#toast').classList.remove('visible'),3800);}
function loadDemo(){try{state={...blankState(),...JSON.parse(localStorage.getItem('lara-demo-state')||'{}')};posts=JSON.parse(localStorage.getItem('lara-demo-posts')||'[]')}catch{state=blankState();posts=[]}user={id:'demo',name:'Visitante',role:'demo'};content=structuredClone(demoContent);}
async function save(){if(demo){try{localStorage.setItem('lara-demo-state',JSON.stringify(state));}catch{toast('O navegador não permitiu salvar seus registros.');throw Error('Armazenamento indisponível');}return;}const snapshot=structuredClone(state);saveQueue=saveQueue.catch(()=>{}).then(()=>api('/state','PUT',snapshot));return saveQueue;}
const workouts=()=>content.filter(c=>c.kind==='workout'),recipes=()=>content.filter(c=>c.kind==='recipe'),guides=()=>content.filter(c=>c.kind==='guide');
const byId=id=>content.find(c=>c.id===id),name=()=>state.profile.name||user?.name||'Visitante',today=()=>dateKey(),niceDate=k=>new Date(k+'T12:00:00').toLocaleDateString('pt-BR',{day:'2-digit',month:'short'});
const header=(title,sub,action='')=>`<div class="page-head row between"><div><h1>${title}</h1><p>${sub}</p></div>${action}</div>`;
const empty=(title,description)=>`<div class="empty">${icon('leaf')}<h3>${title}</h3><p>${description}</p></div>`;
const demoNotice=()=>demo?'<div class="notice">Demonstração • Conteúdos de exemplo e prévias visuais. Seus testes ficam somente neste navegador.</div>':'';
const formField=(label,name,type='text',value='',extra='')=>`<label class="field"><span>${label}</span><input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;
const select=(label,name,options,value)=>`<label><span>${label}</span><select name="${name}">${options.map(o=>`<option value="${esc(Array.isArray(o)?o[0]:o)}" ${(Array.isArray(o)?o[0]:o)==value?'selected':''}>${esc(Array.isArray(o)?o[1]:o)}</option>`).join('')}</select></label>`;
function tabs(items){return `<div class="tabs" role="group" aria-label="Seções">${items.map(([id,label])=>`<button data-action="tab" data-id="${id}" class="${tab===id?'selected':''}" aria-pressed="${tab===id}">${label}</button>`).join('')}</div>`;}
function render(){page=location.hash.slice(1)||'home';if(!user){renderLogin();return;}if(!navs.some(n=>n[0]===page)&&!['notifications','admin','search'].includes(page))page='home';
 $('#app').innerHTML=`<aside class="sidebar">${brand()}<p class="nav-label">MEU ESPAÇO</p><nav class="nav">${navs.map(([id,label])=>`<a href="#${id}" class="${page===id?'active':''}" ${page===id?'aria-current="page"':''}>${icon(id==='care'?'heart':id==='feed'?'book':id)}${label}</a>`).join('')}${user.role==='admin'?`<a href="#admin" class="${page==='admin'?'active':''}">${icon('settings')}Administração</a>`:''}</nav><div class="sidebar-bottom"><div class="support-card">${icon('community')}<h3>Vamos juntas?</h3><p>Um espaço para suas dúvidas e seu acompanhamento.</p><a class="text-link" href="#care">Falar com a equipe ↗</a></div><p class="sidebar-foot">UM PASSO DE CADA VEZ.</p></div></aside><div class="shell"><header class="topbar"><div class="mobile-brand">${brand()}</div><div class="breadcrumb">Meu espaço &nbsp; / &nbsp; <b>${navs.find(n=>n[0]===page)?.[1]||'Lara Castelli'}</b></div><div class="tools"><form class="search" data-form="search">${icon('search')}<input name="q" aria-label="Buscar conteúdo" placeholder="Buscar no meu espaço" value="${esc(search)}"></form><a class="icon-button" href="#notifications" aria-label="Notificações">${icon('bell')}${content.some(c=>c.kind==='announcement'&&!state.read.includes(c.id))?'<i class="dot"></i>':''}</a><a class="top-user" href="#profile"><span class="avatar">${esc(name().slice(0,2).toUpperCase())}</span><div>${esc(name().split(' ')[0])}<small>Meu espaço de cuidado</small></div></a></div></header>${demo?'<div class="demo-bar"><span>PRÉVIA DO WEB APP · MODO DEMONSTRAÇÃO</span><button data-action="logout">Entrar na minha conta</button></div>':''}<main class="main" id="main" tabindex="-1">${pageContent()}</main></div><nav class="bottomnav" aria-label="Menu principal">${[['home','Início'],['training','Treinos'],['food','Alimentação'],['progress','Evolução'],['profile','Mais']].map(([id,label])=>`<a href="#${id}" class="${page===id?'active':''}">${icon(id)}${label}</a>`).join('')}</nav>`;
 if(page==='community')refreshPosts();if(page==='care'&&tab==='support')refreshTickets();if(page==='admin')refreshAdmin();
}
function renderLogin(){ $('#app').innerHTML=`<div class="login"><section class="login-art"><img src="/assets/rotina.png" alt="Lara Castelli na academia">${brand()}<div class="copy"><h1>Mais força.<br>Mais cuidado.<br>Mais você.</h1><p>Seu espaço para cuidar do corpo depois do emagrecimento. Treinos, alimentação e acompanhamento, juntos na sua rotina.</p></div></section><section class="login-form"><div><p class="eyebrow">BEM-VINDA AO SEU ESPAÇO</p><h2 class="spaced">Que bom ter você aqui.</h2><p class="muted">Entre para continuar cuidando de você.</p><form data-form="login">${formField('Seu e-mail','email','email','','required autocomplete="username"')}${formField('Sua senha','password','password','','required autocomplete="current-password"')}<p class="error" id="login-error"></p><button class="btn" type="submit">Entrar no meu espaço ${icon('arrow')}</button></form><p class="small muted">O acesso é liberado pela equipe. Para recuperar sua senha, contate o suporte da sua compra.</p><div class="divider">conheça o que estamos construindo</div><button class="btn light" data-action="demo">Explorar demonstração ${icon('arrow')}</button></div></section></div>`;}
function pageContent(){switch(page){case'home':return home();case'training':return training();case'food':return food();case'progress':return progress();case'care':return care();case'community':return community();case'feed':return feed();case'notifications':return notifications();case'profile':return profile();case'admin':return adminPage();case'search':return searchPage();}}
function home(){const completed=state.completed.filter(c=>weekDays().some(d=>d.key===c.date)).length,water=state.water[today()]||0,first=workouts()[0];return `<div class="welcome"><div><h1>Olá, ${esc(name().split(' ')[0])} <span aria-hidden="true">☀</span></h1><p>Um novo dia para cuidar de você. Vamos começar?</p></div><div class="date-pill">${icon('calendar')}${new Date().toLocaleDateString('pt-BR',{day:'numeric',month:'long'})}</div></div><section class="hero"><div class="hero-copy"><div class="eyebrow">✦ SEU PRÓXIMO PASSO COMEÇA AQUI</div><h2>O corpo muda.<br>Você fica<br><em>mais forte.</em></h2><p>Treino, alimentação e cuidado para acompanhar a sua nova fase.</p><a href="#training" class="btn lime">Ver meus treinos ${icon('arrow')}</a></div><div class="hero-img"><img src="/assets/rotina.png" alt="Lara Castelli em um ambiente de treino"><div class="hero-badge">${icon('heart')}<div><strong>No seu ritmo.</strong>Cada passo conta.</div></div></div></section><div class="stats"><div class="stat"><div class="stat-icon">${icon('training')}</div><div><strong>${completed}<small>/ ${state.profile.frequency} na semana</small></strong><p>Treinos concluídos</p></div></div><div class="stat"><div class="stat-icon">${icon('water')}</div><div><strong>${(water/1000).toLocaleString('pt-BR')}<small>litros hoje</small></strong><p>Sua hidratação</p></div></div><div class="stat"><div class="stat-icon">${icon('progress')}</div><div><strong>${state.checkins.length}<small>registros</small></strong><p>Evolução acompanhada</p></div></div></div><div class="dashboard-grid"><div><div class="section-head"><div><h2>Sua semana, seu ritmo</h2><p>Organize seus treinos e celebre cada etapa.</p></div><a href="#training" data-tab="schedule">Ver minha ficha ↗</a></div><div class="card"><div class="week">${weekDays().map(d=>`<button class="day ${d.key===today()?'today':''} ${state.completed.some(c=>c.date===d.key)?'complete':''}" data-action="day" data-id="${d.key}" aria-label="${d.day} ${d.number}"><small>${d.day}</small><strong>${d.number}</strong><i class="marker"></i></button>`).join('')}</div>${first?`<div class="session-card"><img src="${first.poster||'/assets/treino-poster-1.jpg'}" alt=""><div><span class="label">${demo?'CONHEÇA A EXPERIÊNCIA':'SEU PRÓXIMO TREINO'}</span><h3>${esc(first.title)}</h3><p>${demo?'Prévia de vídeo · Ficha interativa':esc(first.category||'Treino')}</p></div><button class="icon-button" data-action="open" data-id="${first.id}" aria-label="Abrir treino ${esc(first.title)}">${icon('play')}</button></div>`:'<p class="footnote">Seus treinos aparecerão aqui quando a equipe publicar.</p>'}</div><div class="spaced"><div class="section-head"><h2>Comece por aqui</h2><span class="muted"><small>O primeiro passo é seu.</small></span></div><div class="start-grid">${guides().slice(0,3).map((g,i)=>`<button class="start-card" data-action="open" data-id="${g.id}">${icon(['book','heart','leaf'][i])}<strong>${esc(g.title)}</strong><small>Explorar conteúdo ↗</small></button>`).join('')||empty('Seu conteúdo está chegando','A equipe prepara as orientações para esta etapa.')}</div></div></div><aside class="dashboard-aside"><div class="card"><div class="water-head"><h3>Já bebeu água hoje?</h3>${icon('water')}</div><div class="water-total">${(water/1000).toLocaleString('pt-BR')} L <small>${state.profile.waterGoal?`de ${state.profile.waterGoal/1000} L definidos por você`:'registrados hoje'}</small></div><div class="water-drops">${Array.from({length:6},(_,i)=>icon('water',water>(i*250)?'filled':'')).join('')}</div><div class="water-actions"><p>Um cuidado simples<br>na sua rotina.</p><button class="btn light" data-action="water">+ 250 ml</button></div></div><div class="card checkin"><span class="eyebrow">COMO VOCÊ ESTÁ?</span><h3 class="spaced">Seu progresso vai<br>além da balança.</h3><p>Registre como se sente e acompanhe suas conquistas.</p><button class="btn light" data-action="checkin">Fazer meu registro ${icon('arrow')}</button></div></aside></div>`;}
function workoutCard(w,i){return `<button class="card workout-card" data-action="open" data-id="${w.id}"><div class="workout-art"><img src="${w.poster||`/assets/treino-poster-${i%4+1}.jpg`}" alt="" loading="lazy"><span class="tag">${esc(w.category||'Treino')}</span><span class="play">${icon('play')}</span></div><div class="workout-info"><h3>${esc(w.title)}</h3><p>${w.minutes?`${w.minutes} min · `:''}${demo?'Prévia · Conteúdo em preparação':esc(w.level||'Ver orientações')}</p></div></button>`;}
function training(){return header('Meus treinos','Seu plano organizado para você seguir, no seu ritmo.')+tabs([['library','Biblioteca'],['schedule','Minha ficha'],['history','Concluídos']])+demoNotice()+(tab==='schedule'?schedule():tab==='history'?`<div class="stack">${state.completed.length?state.completed.slice().reverse().map(c=>`<div class="card row between"><div><h3>${esc(byId(c.id)?.title||'Treino')}</h3><small>${niceDate(c.date)}</small></div><button class="btn light" data-action="uncomplete" data-id="${c.id}" data-date="${c.date}">Desfazer conclusão</button></div>`).join(''):empty('Seu primeiro treino conta','Ao concluir uma aula, seu registro aparece aqui.')}</div>`:`<div class="filter-row">${select('Mês do plano','month',[[1,'Mês 01'],[2,'Mês 02'],[3,'Mês 03']],month)}</div><div class="content-grid">${workouts().filter(w=>(w.month||1)===month).map(workoutCard).join('')}</div>${!workouts().some(w=>(w.month||1)===month)?empty('Este mês ainda está em preparação','As novas aulas aparecerão aqui assim que forem publicadas.'):''}`);}
function schedule(){const days=weekDays(week),list=workouts();return `<div class="card"><div class="filter-row">${select('Meu objetivo','goal',['Ganhar força','Buscar definição','Criar uma rotina'],state.profile.goal)}${select('Meu nível','level',['Iniciante','Intermediário','Avançado'],state.profile.level)}${select('Disponibilidade','frequency',[[3,'3 dias por semana'],[4,'4 dias por semana'],[5,'5 dias por semana'],[6,'6 dias por semana']],state.profile.frequency)}</div><p class="form-help">As preferências organizam seu calendário. A intensidade, as séries e adaptações seguem a ficha publicada pela equipe.</p><div class="section-head"><button class="btn light" data-action="week" data-id="-1" aria-label="Semana anterior">←</button><h3>${niceDate(days[0].key)} — ${niceDate(days[6].key)}</h3><button class="btn light" data-action="week" data-id="1" aria-label="Próxima semana">→</button></div><button class="btn light" data-action="distribute">Distribuir aulas na semana</button><div class="schedule-list spaced">${days.map((d,i)=>{const planned=state.schedule[d.key]||'',available=suggestedDays(state.profile.frequency).includes(i);return `<div class="schedule-row"><div class="dayname">${d.day} ${d.number}</div><div>${planned?`<button class="tag green" data-action="open" data-id="${esc(planned)}">${esc(byId(planned)?.title||'Treino indisponível')} ↗</button>`:`<span class="muted">${available?'Disponível para treinar':'Descanso / livre'}</span>`}</div><select aria-label="Treino de ${d.day}" data-schedule="${d.key}"><option value="">Sem treino agendado</option>${list.map(w=>`<option value="${w.id}" ${planned===w.id?'selected':''}>${esc(w.title)}</option>`).join('')}</select></div>`}).join('')}</div></div>`;}
function food(){const mealTabs=[['library','Receitas'],['diary','Diário alimentar'],['plan','Meu plano'],['shopping','Lista de compras'],['favorites','Favoritas']];return header('Alimentação','Organização e boas escolhas para o seu dia.')+tabs(mealTabs)+(tab==='diary'?mealDiary():tab==='plan'?`<div class="stack">${guides().filter(g=>g.category==='Plano alimentar').map(g=>`<button class="card" data-action="open" data-id="${g.id}"><h3>${esc(g.title)}</h3><p>Ver orientação publicada ↗</p></button>`).join('')||empty('Seu plano alimentar','A equipe poderá disponibilizar aqui o plano e as orientações revisadas. Não há uma dieta individual cadastrada nesta versão.')}</div>`:tab==='shopping'?`<div class="card"><h2>Sua lista de compras</h2><p class="form-help">Adicione ingredientes a partir de uma receita e marque o que já comprou.</p><form data-form="shopping" class="row"><input name="item" aria-label="Novo item" placeholder="Adicionar um item" required maxlength="150"><button class="btn">Adicionar</button></form><div class="spaced">${state.shopping.map((s,i)=>`<label class="check-row ${s.done?'done':''}"><input type="checkbox" data-shopping="${i}" ${s.done?'checked':''}><span>${esc(s.name)}</span><button type="button" class="text-link" data-action="remove-shopping" data-id="${i}" aria-label="Remover ${esc(s.name)}">×</button></label>`).join('')}</div></div>`:demoNotice()+`<div class="content-grid">${recipes().filter(r=>tab!=='favorites'||state.favorites.includes(r.id)).map((r,i)=>`<article class="card workout-card"><button class="recipe-art ${i===1?'eggs':i===2?'salad':''}" data-action="open" data-id="${r.id}" aria-label="Ver receita ${esc(r.title)}">${r.emoji||'🥗'}</button><div class="workout-info"><span class="tag">${esc(r.category||'Receita')}</span><h3 class="spaced"><button data-action="open" data-id="${r.id}">${esc(r.title)}</button></h3><div class="row between spaced"><small>${r.minutes||'—'} min · Receita</small><button data-action="favorite" data-id="${r.id}" aria-label="Favoritar ${esc(r.title)}" aria-pressed="${state.favorites.includes(r.id)}">${icon('heart',state.favorites.includes(r.id)?'liked':'')}</button></div></div></article>`).join('')}</div>${!recipes().some(r=>tab!=='favorites'||state.favorites.includes(r.id))?empty('Suas receitas aparecerão aqui',tab==='favorites'?'Toque no coração de uma receita para guardar.':'A equipe ainda está preparando a biblioteca.'):''}`);}
function mealDiary(){const meals=state.meals.filter(m=>m.date===today()),total=k=>meals.reduce((s,m)=>s+(Number(m[k])||0),0);return `<div class="row between section-head"><h2>Hoje, ${niceDate(today())}</h2><button class="btn" data-action="meal">${icon('plus')}Registrar refeição</button></div><div class="metric-grid">${[['calories','Calorias','kcal'],['protein','Proteína','g'],['carbs','Carboidratos','g'],['fiber','Fibras','g']].map(([key,label,unit])=>`<div class="metric"><small>${label}</small><strong>${total(key).toLocaleString('pt-BR')} <small>${unit}</small></strong></div>`).join('')}</div><div class="notice">Valores informados por você a partir de rótulos ou do seu plano. Nenhuma estimativa por foto ou meta automática é calculada.</div><div class="card">${meals.map(m=>`<div class="meal-row"><div><span class="tag">${esc(m.category)}</span><h3>${esc(m.title)}</h3><p>${m.calories||0} kcal · ${m.protein||0} g proteína</p></div><button class="btn ghost" data-action="remove-meal" data-id="${m.id}">Remover</button></div>`).join('')||empty('O que teve no seu dia?','Registre sua primeira refeição para acompanhar os valores informados.')}</div>`;}
function chart(){const entries=state.checkins.filter(c=>c.weight).slice(-12);if(entries.length<2)return empty('Cada registro conta','Com dois registros de peso, você começa a visualizar sua evolução no gráfico.');const vals=entries.map(c=>+c.weight),min=Math.min(...vals)-1,max=Math.max(...vals)+1,point=(c,i)=>[40+i*(520/(entries.length-1)),160-(+c.weight-min)/(max-min)*130];return `<svg class="chart" viewBox="0 0 600 200" role="img" aria-label="Evolução do peso conforme seus registros"><line x1="40" y1="165" x2="560" y2="165"/><polyline class="chart-line" points="${entries.map((c,i)=>point(c,i).join(',')).join(' ')}"/>${entries.map((c,i)=>{const[x,y]=point(c,i);return `<circle cx="${x}" cy="${y}" r="4"/><text x="${x}" y="${y-12}" text-anchor="middle">${c.weight} kg</text>${i===0||i===entries.length-1?`<text x="${x}" y="190" text-anchor="middle">${niceDate(c.date)}</text>`:''}`}).join('')}</svg>`;}
function progress(){return header('Minha evolução','Sua história, registrada por você.',`<button class="btn" data-action="checkin">${icon('plus')}Novo registro</button>`)+`<div class="progress-layout"><div class="card"><div class="section-head"><h2>Seu peso ao longo do tempo</h2><span class="tag">kg</span></div>${chart()}</div><div class="card checkin"><span class="eyebrow">CONQUISTAS DA SUA ROTINA</span><h2 class="spaced">${state.completed.length} treinos<br>registrados por você.</h2><p>Acompanhe também disposição, medidas e como você se sente. Cada pessoa tem seu ritmo.</p><button class="btn light" data-action="photos">Ver evolução por fotos ${icon('arrow')}</button></div></div><div class="card spaced"><h2>Meus registros</h2><div class="table-wrap"><table class="history"><thead><tr><th>Data</th><th>Peso</th><th>Cintura</th><th>Quadril</th><th>Como me sinto</th><th></th></tr></thead><tbody>${state.checkins.slice().reverse().map(c=>`<tr><td>${niceDate(c.date)}</td><td>${c.weight?c.weight+' kg':'—'}</td><td>${c.waist?c.waist+' cm':'—'}</td><td>${c.hip?c.hip+' cm':'—'}</td><td>${esc(c.mood||'—')}<br><small>${esc(c.note||'')}</small></td><td><button data-action="remove-checkin" data-id="${c.id}" aria-label="Remover registro de ${c.date}">×</button></td></tr>`).join('')}</tbody></table></div>${!state.checkins.length?'<p class="footnote">Nenhum registro ainda. Comece com o que faz sentido para você acompanhar.</p>':''}</div>`;}
function care(){return header('Acompanhamento','Seus registros e o apoio para continuar.')+tabs([['library','Orientações'],['applications','Aplicações'],['symptoms','Sintomas'],['supplements','Lembretes'],['support','Falar com a equipe']])+(tab==='support'?`<div class="two-col"><form class="card" data-form="ticket"><h2>Envie sua dúvida</h2><p class="form-help">A equipe responderá por aqui. Este canal não oferece atendimento de urgência.</p><label class="field"><span>Sua mensagem</span><textarea name="body" required maxlength="3000" placeholder="Conte como podemos ajudar"></textarea></label><button class="btn">${demo?'Salvar dúvida na demonstração':'Enviar para a equipe'}</button></form><div id="tickets" class="stack"></div></div>`:tab==='applications'?`<div class="notice">Registre apenas a aplicação e a próxima data já orientadas pelo seu prescritor. O sistema não calcula doses nem recomenda medicamentos.</div><button class="btn" data-action="application">${icon('plus')}Registrar aplicação</button><div class="stack spaced">${state.applications.slice().reverse().map(a=>`<div class="card row between"><div><h3>${esc(a.name)}</h3><p>${esc(a.dose)} · ${niceDate(a.date)}</p><small>Próxima data informada: ${a.next?niceDate(a.next):'não informada'}</small></div><button class="btn ghost" data-action="remove-application" data-id="${a.id}">Remover</button></div>`).join('')||empty('Seus registros de aplicação','Guarde as informações do seu tratamento, sem sugestões automáticas de dose.')}</div>`:tab==='symptoms'?`<button class="btn" data-action="symptom">${icon('plus')}Registrar como me sinto</button><div class="stack spaced">${state.symptoms.slice().reverse().map(s=>`<div class="card row between"><div><h3>${esc(s.name)} <span class="tag">${s.intensity}/10</span></h3><small>${niceDate(s.date)}</small><p>${esc(s.note)}</p></div><button class="btn ghost" data-action="remove-symptom" data-id="${s.id}">Remover</button></div>`).join('')||empty('Como você tem se sentido?','Um diário para compartilhar com seu profissional, sem diagnóstico automático.')}</div>`:tab==='supplements'?`<div class="notice">Lembretes aparecem neste aplicativo quando você o abre. Notificações push, e-mail e WhatsApp ainda não estão integrados.</div><button class="btn" data-action="supplement">${icon('plus')}Criar lembrete</button><div class="stack spaced">${state.supplements.map(s=>`<div class="card row between"><div><h3>${esc(s.name)}</h3><small>${s.date?niceDate(s.date):'Todos os dias'} · ${esc(s.time)}</small><p>${esc(s.note)}</p></div><button class="btn ghost" data-action="remove-supplement" data-id="${s.id}">Remover</button></div>`).join('')||empty('Lembretes da sua rotina','Organize horários de hábitos ou cuidados já definidos por você e sua equipe.')}</div>`:`<div class="stack">${guides().map(g=>`<button class="card row between" data-action="open" data-id="${g.id}"><div><span class="tag">${esc(g.category)}</span><h3 class="spaced">${esc(g.title)}</h3></div>${icon('arrow')}</button>`).join('')||empty('Orientações em preparação','Os conteúdos revisados serão publicados aqui.')}</div>`);}
function community(){return header('Comunidade','Um espaço para compartilhar rotina e pequenas conquistas.')+`<div class="community-layout">${demo?'<div class="notice">Publicações de teste ficam neste navegador. Nenhuma mensagem é enviada a outras pessoas.</div>':''}<form data-form="post" class="card"><label class="field"><span>Como foi seu dia?</span><textarea name="body" placeholder="Compartilhe uma conquista, uma experiência ou uma dúvida…" maxlength="2000" required></textarea></label><div class="row between"><small>Compartilhe apenas o que você deseja tornar visível às outras alunas.</small><button class="btn">${demo?'Salvar teste':'Publicar'}</button></div></form><div id="posts" class="spaced"></div></div>`;}
async function refreshPosts(){try{if(!demo)posts=await api('/posts');if(page!=='community')return;$('#posts').innerHTML=posts.map(p=>`<article class="card post"><div class="post-head"><span class="avatar">${esc(p.name.slice(0,2).toUpperCase())}</span><div><strong>${esc(p.name)}</strong><small>${new Date(p.created_at.endsWith('Z')?p.created_at:p.created_at+'Z').toLocaleDateString('pt-BR')}</small></div></div><p>${esc(p.body)}</p><div class="post-actions"><button data-action="like" data-id="${p.id}" class="${p.liked?'liked':''}">${icon('heart')}${p.likes||0} curtidas</button>${p.user_id===user.id||user.role==='admin'?`<button data-action="delete-post" data-id="${p.id}">Excluir</button>`:''}</div>${(p.comments||[]).map(c=>`<div class="comment"><b>${esc(c.name)}</b><p>${esc(c.body)}</p></div>`).join('')}<form class="row spaced" data-form="comment" data-id="${p.id}"><input name="body" placeholder="Escreva um comentário" aria-label="Comentário" required maxlength="1000"><button class="btn light">Comentar</button></form></article>`).join('')||empty('Vamos começar uma conversa?','As publicações da comunidade aparecerão aqui.');}catch(e){toast(e.message);}}
function feed(){return header('Novidades','Avisos e conteúdos da equipe.')+`<div class="stack">${content.filter(c=>c.kind==='announcement').map(c=>`<article class="card"><span class="tag">Equipe Lara Castelli</span><h2 class="spaced">${esc(c.title)}</h2><p class="guide-body">${esc(c.description)}</p></article>`).join('')||empty('Você está em dia','Quando houver novidades, você verá os avisos aqui.')}</div>`;}
function notifications(){const notices=content.filter(c=>c.kind==='announcement');const reminders=[...state.supplements.filter(s=>!s.date||s.date===today()).map(s=>({id:s.id,title:s.name,description:`Hoje, ${s.time}. ${s.note||''}`})),...state.applications.filter(a=>a.next===today()).map(a=>({id:a.id,title:'Data de aplicação registrada',description:`${a.name}: confira a orientação do seu prescritor.`}))];return header('Notificações','Seus avisos e lembretes em um só lugar.')+`<div class="notifications">${[...reminders,...notices].map(n=>`<article class="card notification ${state.read.includes(n.id)?'read':''}"><span class="stat-icon">${icon('bell')}</span><div><h3>${esc(n.title)}</h3><p>${esc(n.description)}</p></div><button class="btn light" data-action="read" data-id="${n.id}">${state.read.includes(n.id)?'Lida':'Marcar como lida'}</button></article>`).join('')||empty('Tudo em dia','Os novos avisos e lembretes aparecerão aqui.')}</div>`;}
function profile(){return header('Meu perfil','Suas preferências e seus dados.')+`<div class="profile-grid"><form data-form="profile" class="card"><h2>Do seu jeito</h2><div class="spaced">${formField('Como você quer ser chamada?','name','text',name(),'required maxlength="80"')}${select('Objetivo','goal',['Ganhar força','Buscar definição','Criar uma rotina'],state.profile.goal)}<div class="spaced">${select('Meu nível','level',['Iniciante','Intermediário','Avançado'],state.profile.level)}</div><div class="spaced">${select('Disponibilidade semanal','frequency',[[3,'3 dias'],[4,'4 dias'],[5,'5 dias'],[6,'6 dias']],state.profile.frequency)}</div><div class="spaced">${formField('Meta de água orientada para você (ml, opcional)','waterGoal','number',state.profile.waterGoal||'','min="0" max="10000" step="50"')}</div><button class="btn">Salvar preferências</button></div></form><div class="stack"><div class="card"><h2>Explore seu espaço</h2><nav class="nav">${[['care','Acompanhamento'],['community','Comunidade'],['feed','Novidades'],['notifications','Notificações'],...(user.role==='admin'?[['admin','Administração']]:[])].map(([id,label])=>`<a href="#${id}">${icon('arrow')}${label}</a>`).join('')}</nav></div><div class="card"><h2>Seus dados</h2><p class="form-help">${demo?'Os registros desta demonstração ficam no navegador.':'Seus registros individuais ficam vinculados à sua conta. Publicações e comentários são visíveis à comunidade.'}</p><div class="row wrap"><button class="btn light" data-action="export">Exportar meus registros</button><button class="btn light" data-action="logout">${icon('logout')}Sair</button></div></div></div></div>`;}
function searchPage(){const list=content.filter(c=>(c.title+' '+c.description).toLowerCase().includes(search.toLowerCase()));return header('Buscar no meu espaço',`Resultados para “${esc(search)}”`)+`<form class="row" data-form="search"><input name="q" value="${esc(search)}" aria-label="Buscar conteúdo" required><button class="btn">Buscar</button></form><div class="stack spaced">${list.map(c=>`<button class="card row between" data-action="open" data-id="${c.id}"><h3>${esc(c.title)}</h3>${icon('arrow')}</button>`).join('')||empty('Nenhum conteúdo encontrado','Tente buscar por outro termo.')}</div>`;}
function adminPage(){if(user.role!=='admin')return empty('Acesso restrito','Entre com uma conta de administração.');return header('Administração','Gerencie conteúdos, acessos e acompanhamento.')+tabs([['library','Conteúdos'],['users','Alunas'],['support','Atendimento']])+`<div id="admin-content"></div>`;}
let adminContent=[],adminUsers=[];
async function refreshAdmin(){if(user.role!=='admin')return;try{if(tab==='support'){tickets=await api('/tickets');if(page!=='admin')return;$('#admin-content').innerHTML=tickets.map(t=>`<form data-form="reply" data-id="${t.id}" class="card spaced"><h3>${esc(t.name)}</h3><p class="guide-body">${esc(t.body)}</p><label class="field"><span>Resposta</span><textarea name="reply" required maxlength="3000">${esc(t.reply)}</textarea></label><button class="btn">Salvar resposta</button></form>`).join('')||empty('Nenhum atendimento pendente','As dúvidas enviadas pelas alunas aparecerão aqui.');}else if(tab==='users'){adminUsers=await api('/admin/users');if(page!=='admin')return;$('#admin-content').innerHTML=`<button class="btn" data-action="new-user">${icon('plus')}Cadastrar aluna</button><div class="admin-list spaced">${adminUsers.map(u=>`<div class="card admin-item"><div><h3>${esc(u.name)}</h3><small>${esc(u.email)} · ${u.role==='admin'?'Administração':u.active?'Acesso ativo':'Acesso suspenso'}</small></div>${u.id!==user.id?`<div class="row"><button class="btn light" data-action="toggle-user" data-id="${u.id}">${u.active?'Suspender':'Reativar'}</button><button class="btn light" data-action="reset-password" data-id="${u.id}">Nova senha</button></div>`:''}</div>`).join('')}</div>`;}else{adminContent=await api('/admin/content');if(page!=='admin')return;$('#admin-content').innerHTML=`<button class="btn" data-action="edit-content">${icon('plus')}Novo conteúdo</button><div class="admin-list spaced">${adminContent.map(c=>`<div class="card admin-item"><div><span class="tag">${c.published?'Publicado':'Rascunho'} · ${esc(c.kind)}</span><h3>${esc(c.title)}</h3></div><button class="btn light" data-action="edit-content" data-id="${c.id}">Editar</button></div>`).join('')||empty('Comece pelos seus conteúdos','Cadastre aulas, receitas, orientações e avisos. Rascunhos ficam visíveis somente à administração.')}</div>`;}}catch(e){toast(e.message);}}
async function refreshTickets(){try{if(demo){tickets=JSON.parse(localStorage.getItem('lara-demo-tickets')||'[]')}else tickets=await api('/tickets');if(!$('#tickets'))return;$('#tickets').innerHTML=tickets.map(t=>`<div class="card"><span class="tag">${t.reply?'Respondida':demo?'Teste local':'Aguardando equipe'}</span><p class="guide-body">${esc(t.body)}</p>${t.reply?`<hr><strong>Equipe</strong><p class="guide-body">${esc(t.reply)}</p>`:''}</div>`).join('')||empty('Suas conversas','Você poderá acompanhar suas dúvidas e respostas aqui.');}catch(e){toast(e.message);}}
function modal(title,body){clearInterval(timerId);const d=$('#modal');d.innerHTML=`<div class="modal-head"><h2>${esc(title)}</h2><button class="icon-button" data-action="close" aria-label="Fechar">${icon('close')}</button></div><div class="modal-body">${body}</div>`;if(!d.open)d.showModal();}
function closeModal(){const video=$('#modal video');if(video){video.pause();}clearInterval(timerId);$('#modal').close();}
function openContent(id){const c=byId(id);if(!c)return toast('Conteúdo indisponível.');if(c.kind==='workout'){timerRemaining=60;modal(c.title,`${demo?'<div class="notice">Prévia visual. A aula completa e a ficha profissional ainda serão cadastradas.</div>':''}${c.video?`<video id="workout-video" controls playsinline preload="metadata" src="${esc(c.video)}" poster="${c.poster||'/assets/treino-poster-1.jpg'}"></video><div class="row between video-note"><span>${demo?'Clipe de apresentação':'Vídeo da aula'}</span><label>Velocidade <select id="speed" aria-label="Velocidade do vídeo"><option>0.75</option><option selected>1</option><option>1.25</option><option>1.5</option></select></label></div>`:'<div class="empty"><h3>Vídeo em preparação</h3><p>A equipe publicará o vídeo aqui.</p></div>'}<p class="guide-body">${esc(c.description)}</p><div class="filter-row">${select('Nível da ficha','workout-level',['Iniciante','Intermediário','Avançado'],state.profile.level)}</div><h3>Sua ficha de exercícios</h3>${(c.exercises||[]).map((e,i)=>`<label class="exercise"><input type="checkbox" data-exercise="${id}:${today()}:${i}" ${state.exerciseChecks[`${id}:${today()}:${i}`]?'checked':''}><div><strong>${esc(e.name)}</strong><small>${esc((state.profile.level==='Iniciante'?e.beginner:state.profile.level==='Intermediário'?e.intermediate:e.advanced)||e.detail)}</small></div></label>`).join('')}<div class="timer"><div><small>Descanso • ajuste conforme sua ficha</small><strong id="timer-clock">01:00</strong><small id="timer-status">Pronto para iniciar</small></div><label><span>Segundos</span><input id="timer-seconds" type="number" min="5" max="600" value="60"></label><div class="row"><button class="btn" data-action="timer">Iniciar</button><button class="btn light" data-action="timer-reset">Reiniciar</button></div></div><button class="btn" data-action="complete" data-id="${id}">${icon('check')}${state.completed.some(x=>x.id===id&&x.date===today())?'Concluído hoje · desfazer':'Marcar como concluído'}</button>${c.reviewer?`<p class="footnote">Responsável pela revisão: ${esc(c.reviewer)}</p>`:''}`);const video=$('#workout-video');if(video){video.addEventListener('loadedmetadata',()=>{const pos=state.videoPositions[id];if(pos&&pos<video.duration)video.currentTime=pos;});video.addEventListener('pause',()=>{state.videoPositions[id]=video.currentTime;save().catch(e=>toast(e.message));});}}else if(c.kind==='recipe'){modal(c.title,`${demoNotice()}<span class="tag">${esc(c.category)} · ${c.minutes||'—'} min</span><p class="guide-body">${esc(c.description)}</p><h3>Ingredientes</h3><ul class="list">${(c.ingredients||[]).map(i=>`<li>${esc(i)}</li>`).join('')}</ul><h3>Modo de preparo</h3><ol class="list">${(c.steps||[]).map(s=>`<li>${esc(s)}</li>`).join('')}</ol><div class="modal-actions"><button class="btn" data-action="add-ingredients" data-id="${id}">Adicionar à lista de compras</button><button class="btn light" data-action="favorite" data-id="${id}">${state.favorites.includes(id)?'Remover das favoritas':'Guardar receita'}</button></div>`);}else modal(c.title,`<p class="guide-body">${esc(c.description)}</p>${c.reviewer?`<p class="footnote">Revisão: ${esc(c.reviewer)}</p>`:''}<button class="btn" data-action="read" data-id="${id}">Marcar como lido</button>`);}
function checkinForm(){modal('Como você está hoje?',`<form data-form="checkin">${formField('Data','date','date',today(),'required max="'+today()+'"')}<div class="row">${formField('Peso (kg, opcional)','weight','number','','min="20" max="500" step="0.1"')}${formField('Cintura (cm, opcional)','waist','number','','min="20" max="300" step="0.1"')}</div>${formField('Quadril (cm, opcional)','hip','number','','min="20" max="300" step="0.1"')}${select('Como me sinto','mood',['Bem','Com energia','Cansada','Desanimada','Prefiro não informar'],'Bem')}<label class="field spaced"><span>Uma conquista ou observação</span><textarea name="note" maxlength="500" placeholder="O que você gostaria de registrar?"></textarea></label><button class="btn">Salvar registro</button></form>`);}
function entryForm(type){const forms={meal:['Registrar refeição',`${select('Refeição','category',['Café da manhã','Almoço','Lanche','Jantar','Outra'],'Almoço')}<div class="spaced">${formField('O que você comeu?','title','text','','required maxlength="150"')}</div><div class="row">${formField('Calorias (kcal)','calories','number','','min="0" max="10000" step="0.1"')}${formField('Proteína (g)','protein','number','','min="0" max="1000" step="0.1"')}</div><div class="row">${formField('Carboidratos (g)','carbs','number','','min="0" max="1000" step="0.1"')}${formField('Fibras (g)','fiber','number','','min="0" max="1000" step="0.1"')}</div><p class="form-help">Preencha os valores disponíveis no rótulo ou no seu plano.</p>`],application:['Registrar aplicação',`${formField('Medicamento prescrito','name','text','','required maxlength="100"')}${formField('Dose aplicada, conforme prescrição','dose','text','','required maxlength="80"')}${formField('Data da aplicação','date','date',today(),'required max="'+today()+'"')}${formField('Próxima data orientada (opcional)','next','date','','min="'+today()+'"')}<p class="form-help">Registro pessoal. Não é uma indicação de medicamento ou de dose.</p>`],symptom:['Registrar sintoma',`${formField('O que você está sentindo?','name','text','','required maxlength="100"')}${formField('Data','date','date',today(),'required max="'+today()+'"')}${formField('Intensidade percebida (0 a 10)','intensity','number',5,'required min="0" max="10"')}<label class="field"><span>Observações</span><textarea name="note" maxlength="500"></textarea></label>`],supplement:['Criar lembrete',`${formField('O que lembrar?','name','text','','required maxlength="100"')}${formField('Horário','time','time','09:00','required')}${formField('Data (deixe vazia para todos os dias)','date','date')}${formField('Observação, se houver','note','text','','maxlength="300"')}<p class="form-help">O lembrete será mostrado dentro do aplicativo. Não haverá alerta com o navegador fechado.</p>`]};const[title,body]=forms[type];modal(title,`<form data-form="${type}">${body}<button class="btn">Salvar registro</button></form>`);}
function contentForm(id){const c=adminContent.find(x=>x.id===id)||{id:crypto.randomUUID(),kind:'workout',month:1};modal(c.title?'Editar conteúdo':'Novo conteúdo',`<form data-form="content" data-id="${c.id}">${select('Tipo','kind',[['workout','Treino'],['recipe','Receita'],['guide','Orientação / plano'],['announcement','Aviso']],c.kind)}<div class="spaced">${formField('Título','title','text',c.title,'required maxlength="150"')}${formField('Categoria (use Plano alimentar para dietas)','category','text',c.category,'maxlength="60"')}</div><label class="field"><span>Descrição / orientação</span><textarea name="description" maxlength="12000">${esc(c.description||'')}</textarea></label>${formField('URL do vídeo MP4 ou arquivo enviado','video','text',c.video)}<label class="field"><span>Enviar vídeo MP4 para a VPS (até 500 MB)</span><input id="upload-video" type="file" accept="video/mp4"></label><p id="upload-status" class="form-help">O upload fica protegido pelo acesso das alunas. Aguarde terminar antes de salvar o conteúdo.</p><div class="row">${formField('Mês','month','number',c.month||1,'min="1" max="12"')}${formField('Duração em minutos','minutes','number',c.minutes||0,'min="0" max="180"')}</div>${formField('Nível e adaptações','level','text',c.level)}<label class="field"><span>Exercícios — uma linha: nome | iniciante | intermediário | avançado</span><textarea name="exercises">${esc((c.exercises||[]).map(e=>e.name+' | '+(e.beginner||e.detail)+' | '+(e.intermediate||e.detail)+' | '+(e.advanced||e.detail)).join('\n'))}</textarea></label><label class="field"><span>Ingredientes — um por linha</span><textarea name="ingredients">${esc((c.ingredients||[]).join('\n'))}</textarea></label><label class="field"><span>Modo de preparo — uma etapa por linha</span><textarea name="steps">${esc((c.steps||[]).join('\n'))}</textarea></label>${formField('Responsável pela revisão (nome e registro profissional)','reviewer','text',c.reviewer)}<label class="check-row"><input type="checkbox" name="published" ${c.published?'checked':''}><span>Publicar para as alunas</span></label><p class="form-help">Treinos, receitas e orientações exigem identificação de revisão. Avisos não exigem esse campo. Preencha conteúdo específico por nível na ficha.</p><button class="btn">Salvar conteúdo</button></form>`);}
function exportData(){const blob=new Blob([JSON.stringify({exportedAt:new Date().toISOString(),...state},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='meus-registros-lara-castelli.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
document.addEventListener('click',async event=>{const tabLink=event.target.closest('[data-tab]');if(tabLink)tab=tabLink.dataset.tab;const b=event.target.closest('[data-action]');if(!b)return;const{id,action}=b.dataset;try{switch(action){case'demo':demo=true;sessionStorage.setItem('lara-demo','1');loadDemo();location.hash='home';render();break;case'logout':if(!demo)await api('/logout','POST',{});demo=false;sessionStorage.removeItem('lara-demo');user=null;state=blankState();closeModal();renderLogin();break;case'open':openContent(id);break;case'close':closeModal();break;case'tab':tab=id;render();break;case'water':state.water[today()]=(state.water[today()]||0)+250;await save();render();toast('250 ml registrados.');break;case'checkin':checkinForm();break;case'day':tab='schedule';location.hash='training';render();break;case'week':week+=Number(id);render();break;case'distribute':{const lessons=workouts();if(!lessons.length){toast('Ainda não há aulas publicadas.');break;}const available=suggestedDays(state.profile.frequency);let index=0;for(const [i,d]of weekDays(week).entries()){state.schedule[d.key]=available.includes(i)?lessons[index++%lessons.length].id:'';}await save();render();toast('Aulas distribuídas. Você pode ajustar cada dia.');break;}case'favorite':state.favorites=state.favorites.includes(id)?state.favorites.filter(x=>x!==id):[...state.favorites,id];await save();if($('#modal').open)openContent(id);else render();break;case'add-ingredients':for(const ingredient of byId(id).ingredients||[])if(!state.shopping.some(s=>s.name===ingredient))state.shopping.push({name:ingredient,done:false});await save();toast('Ingredientes adicionados à lista de compras.');break;case'remove-shopping':state.shopping.splice(Number(id),1);await save();render();break;case'complete':{const done=state.completed.findIndex(x=>x.id===id&&x.date===today());if(done>=0)state.completed.splice(done,1);else state.completed.push({id,date:today()});await save();closeModal();render();toast(done>=0?'Conclusão desfeita.':'Treino registrado. Um passo a mais por você!');break;}case'uncomplete':state.completed=state.completed.filter(c=>!(c.id===id&&c.date===b.dataset.date));await save();render();break;case'timer':if(timerId){timerRemaining=Math.max(0,Math.ceil((timerEnd-Date.now())/1000));clearInterval(timerId);timerId=null;b.textContent='Continuar';$('#timer-status').textContent='Pausado';}else{if(timerRemaining===0)timerRemaining=Number($('#timer-seconds').value)||60;timerEnd=Date.now()+timerRemaining*1000;b.textContent='Pausar';$('#timer-status').textContent='Descansando';timerId=setInterval(()=>{timerRemaining=Math.max(0,Math.ceil((timerEnd-Date.now())/1000));$('#timer-clock').textContent=`${String(Math.floor(timerRemaining/60)).padStart(2,'0')}:${String(timerRemaining%60).padStart(2,'0')}`;if(!timerRemaining){clearInterval(timerId);timerId=null;b.textContent='Iniciar';$('#timer-status').textContent='Tempo concluído';toast('Descanso concluído.');}},200);}break;case'timer-reset':clearInterval(timerId);timerId=null;timerRemaining=Math.max(5,Math.min(600,Number($('#timer-seconds').value)||60));$('#timer-clock').textContent=`${String(Math.floor(timerRemaining/60)).padStart(2,'0')}:${String(timerRemaining%60).padStart(2,'0')}`;$('#timer-status').textContent='Pronto para iniciar';$('[data-action="timer"]').textContent='Iniciar';break;case'read':if(!state.read.includes(id))state.read.push(id);await save();closeModal();render();toast('Marcado como lido.');break;case'meal':case'application':case'symptom':case'supplement':entryForm(action);break;case'remove-meal':case'remove-application':case'remove-symptom':case'remove-supplement':case'remove-checkin':{const key={'remove-meal':'meals','remove-application':'applications','remove-symptom':'symptoms','remove-supplement':'supplements','remove-checkin':'checkins'}[action];state[key]=state[key].filter(x=>x.id!==id);await save();render();break;}case'export':exportData();break;case'like':if(demo){const p=posts.find(x=>x.id===id);p.liked=!p.liked;p.likes=p.liked?1:0;localStorage.setItem('lara-demo-posts',JSON.stringify(posts));}else await api('/posts/'+id+'/like','POST',{});refreshPosts();break;case'delete-post':modal('Excluir publicação?',`<p>Esta ação remove a publicação e seus comentários.</p><div class="modal-actions"><button class="btn danger" data-action="confirm-delete-post" data-id="${id}">Excluir publicação</button><button class="btn light" data-action="close">Cancelar</button></div>`);break;case'confirm-delete-post':if(demo){posts=posts.filter(x=>x.id!==id);localStorage.setItem('lara-demo-posts',JSON.stringify(posts));}else await api('/posts/'+id,'DELETE');closeModal();refreshPosts();break;case'edit-content':contentForm(id);break;case'new-user':modal('Cadastrar aluna',`<form data-form="new-user">${formField('Nome','name','text','','required maxlength="100"')}${formField('E-mail','email','email','','required')}${formField('Senha inicial (mínimo 12 caracteres)','password','password','','required minlength="12" autocomplete="new-password"')}<button class="btn">Criar acesso</button></form>`);break;case'toggle-user':{const u=adminUsers.find(u=>u.id===id);await api('/admin/users/'+id,'PUT',{active:!u.active});refreshAdmin();break;}case'reset-password':modal('Definir nova senha',`<form data-form="reset-password" data-id="${id}">${formField('Nova senha','password','password','','required minlength="12" autocomplete="new-password"')}<p class="form-help">As sessões anteriores serão encerradas.</p><button class="btn">Salvar nova senha</button></form>`);break;case'photos':await showPhotos();break;case'remove-photo':await removePhoto(id);break;}}catch(e){toast(e.message);}});
document.addEventListener('change',async event=>{const el=event.target;try{if(el.id==='upload-video'){const file=el.files[0];if(!file)return;if(file.size>500*1024*1024||file.type!=='video/mp4')throw Error('Use um arquivo MP4 de até 500 MB.');const button=el.form.querySelector('button');button.disabled=true;el.disabled=true;$('#upload-status').textContent='Enviando vídeo…';try{const r=await fetch('/api/admin/media',{method:'POST',headers:{'Content-Type':'video/mp4'},body:file});const result=await r.json();if(!r.ok)throw Error(result.error);el.form.elements.video.value=result.url;$('#upload-status').textContent='Vídeo enviado. Salve o conteúdo para vincular.';}finally{el.disabled=false;button.disabled=false;}}else if(el.dataset.schedule){state.schedule[el.dataset.schedule]=el.value;await save();render();}else if(el.dataset.shopping!==undefined){state.shopping[Number(el.dataset.shopping)].done=el.checked;await save();render();}else if(el.dataset.exercise){state.exerciseChecks[el.dataset.exercise]=el.checked;await save();}else if(el.name==='workout-level'){state.profile.level=el.value;await save();const id=$('#modal [data-action="complete"]').dataset.id;openContent(id);}else if(el.id==='speed')$('#workout-video').playbackRate=Number(el.value);else if(el.id==='timer-seconds'){timerRemaining=Math.max(5,Math.min(600,Number(el.value)||60));el.value=timerRemaining;$('[data-action="timer-reset"]').click();}else if(el.name==='month'&&!el.closest('dialog')){month=Number(el.value);render();}else if(['frequency','level','goal'].includes(el.name)&&page==='training'){state.profile[el.name]=el.name==='frequency'?Number(el.value):el.value;await save();render();}}catch(e){toast(e.message);}});
document.addEventListener('submit',async event=>{const form=event.target.closest('[data-form]');if(!form)return;event.preventDefault();const data=Object.fromEntries(new FormData(form)),kind=form.dataset.form,submit=form.querySelector('button[type="submit"],button:not([type])');if(submit)submit.disabled=true;try{switch(kind){case'login':{const r=await api('/login','POST',data);user=r.user;demo=false;sessionStorage.removeItem('lara-demo');state={...blankState(),...await api('/state')};content=await api('/content');tab='library';location.hash='home';render();break;}case'profile':state.profile={...state.profile,...data,frequency:Number(data.frequency),waterGoal:Number(data.waterGoal)||0};await save();toast('Preferências salvas.');render();break;case'checkin':state.checkins.push({...data,id:crypto.randomUUID()});state.checkins.sort((a,b)=>a.date.localeCompare(b.date));await save();closeModal();render();toast('Seu registro foi salvo.');break;case'shopping':state.shopping.push({name:data.item.trim(),done:false});await save();render();break;case'meal':case'application':case'symptom':case'supplement':{const key={meal:'meals',application:'applications',symptom:'symptoms',supplement:'supplements'}[kind];state[key].push({...data,date:kind==='meal'?today():data.date,id:crypto.randomUUID()});await save();closeModal();render();toast('Registro salvo.');break;}case'post':if(demo){posts.unshift({id:crypto.randomUUID(),user_id:'demo',name:name(),body:data.body,likes:0,liked:false,comments:[],created_at:new Date().toISOString()});localStorage.setItem('lara-demo-posts',JSON.stringify(posts));}else await api('/posts','POST',data);form.reset();refreshPosts();toast(demo?'Publicação salva somente na demonstração.':'Publicado.');break;case'comment':if(demo){posts.find(p=>p.id===form.dataset.id).comments.push({name:name(),body:data.body});localStorage.setItem('lara-demo-posts',JSON.stringify(posts));}else await api('/posts/'+form.dataset.id+'/comments','POST',data);refreshPosts();break;case'ticket':if(demo){tickets.unshift({id:crypto.randomUUID(),body:data.body,reply:''});localStorage.setItem('lara-demo-tickets',JSON.stringify(tickets));}else await api('/tickets','POST',data);form.reset();refreshTickets();toast(demo?'Dúvida salva localmente.':'Mensagem enviada para a equipe.');break;case'reply':await api('/tickets/'+form.dataset.id,'PUT',data);toast('Resposta salva.');refreshAdmin();break;case'search':search=data.q.trim();location.hash='search';render();break;case'new-user':await api('/admin/users','POST',data);closeModal();refreshAdmin();toast('Acesso criado.');break;case'reset-password':await api('/admin/users/'+form.dataset.id,'PUT',data);closeModal();toast('Senha atualizada.');break;case'content':data.published=!!data.published;data.exercises=data.exercises.split('\n').filter(x=>x.trim()).map(x=>{const[n,...d]=x.split('|');return{name:n.trim(),detail:(d[0]||'').trim(),beginner:(d[0]||'').trim(),intermediate:(d[1]||d[0]||'').trim(),advanced:(d[2]||d[0]||'').trim()}});data.ingredients=data.ingredients.split('\n').filter(x=>x.trim());data.steps=data.steps.split('\n').filter(x=>x.trim());await api('/admin/content/'+form.dataset.id,'PUT',data);content=await api('/content');closeModal();refreshAdmin();toast('Conteúdo salvo.');break;case'photo':await savePhoto(form);break;}}catch(e){if(kind==='login')$('#login-error').textContent=e.message;else toast(e.message);}finally{if(submit)submit.disabled=false;}});
$('#modal').addEventListener('close',()=>{clearInterval(timerId);timerId=null;$('#modal video')?.pause();});
window.addEventListener('hashchange',()=>{if(!['training','food','care','admin'].includes(location.hash.slice(1)))tab='library';closeModal();render();window.scrollTo(0,0);});
let photos=[];
async function showPhotos(){photos=demo?JSON.parse(localStorage.getItem('lara-demo-photos')||'[]'):await api('/photos');modal('Minha evolução por fotos',`<p class="form-help">${demo?'Fotos de teste ficam apenas neste navegador.':'Fotos individuais são privadas, acessíveis somente pela sua conta.'} JPEG, PNG ou WebP. Até 4 MB por foto.</p><form data-form="photo">${formField('Data','date','date',today(),'required max="'+today()+'"')}<label class="field"><span>Selecionar foto</span><input name="photo" type="file" accept="image/jpeg,image/png,image/webp" required></label><button class="btn">Guardar foto</button></form><div class="content-grid spaced">${photos.map(p=>`<div class="card"><img src="${demo?p.data:'/api/photos/'+p.id}" alt="Registro pessoal de ${esc(p.date)}"><p>${niceDate(p.date)}</p><button class="btn light" data-action="remove-photo" data-id="${p.id}">Remover</button></div>`).join('')}</div>`);}
async function savePhoto(form){const file=form.elements.photo.files[0];if(!file||file.size>4*1024*1024||!['image/jpeg','image/png','image/webp'].includes(file.type))throw Error('Escolha JPEG, PNG ou WebP de até 4 MB.');const data=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file)});if(demo){photos.push({id:crypto.randomUUID(),date:form.elements.date.value,data});try{localStorage.setItem('lara-demo-photos',JSON.stringify(photos));}catch{photos.pop();throw Error('Espaço do navegador insuficiente para esta foto.');}}else await api('/photos','POST',{date:form.elements.date.value,data});await showPhotos();toast('Foto salva.');}
async function removePhoto(id){if(demo){photos=photos.filter(p=>p.id!==id);localStorage.setItem('lara-demo-photos',JSON.stringify(photos));}else await api('/photos/'+id,'DELETE');await showPhotos();}
try{if(demo)loadDemo();else{const r=await api('/me');user=r.user;if(user){state={...blankState(),...await api('/state')};content=await api('/content');}}render();}catch{renderLogin();toast('Não foi possível conectar. Você pode explorar a demonstração.');}
